// fbtcal — SteamVR driver that rewrites tracker poses in place.
// Hooks IVRServerDriverHost::TrackedDevicePoseUpdated (same technique as
// OpenVR-SpaceCalibrator), publishes each device's real pose to shared memory and
// applies the per-tracker offset / override the calibrator app writes there.
#include <openvr_driver.h>
#include "fbtcal_shm.h"

#include <atomic>
#include <mutex>
#include <cstring>
#include <cstdio>
#include <cstdarg>
#include <string>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <time.h>
#include <unistd.h>

using namespace vr;

static FbtcalShared *g_shm = nullptr;

static void Log(const char *fmt, ...)
{
	char buf[512];
	va_list ap;
	va_start(ap, fmt);
	vsnprintf(buf, sizeof buf, fmt, ap);
	va_end(ap);
	if (VRDriverLog()) VRDriverLog()->Log((std::string("[fbtcal] ") + buf).c_str());
}

static uint64_t NowNs()
{
	timespec ts;
	clock_gettime(CLOCK_MONOTONIC, &ts);
	return uint64_t(ts.tv_sec) * 1000000000ull + ts.tv_nsec;
}

// ---- quaternion helpers (w x y z) ----
static HmdQuaternion_t QMul(const HmdQuaternion_t &a, const HmdQuaternion_t &b)
{
	return {
		a.w * b.w - a.x * b.x - a.y * b.y - a.z * b.z,
		a.w * b.x + a.x * b.w + a.y * b.z - a.z * b.y,
		a.w * b.y - a.x * b.z + a.y * b.w + a.z * b.x,
		a.w * b.z + a.x * b.y - a.y * b.x + a.z * b.w,
	};
}

static void QRot(const HmdQuaternion_t &q, const double v[3], double out[3])
{
	// out = q * v * q^-1
	double tx = 2 * (q.y * v[2] - q.z * v[1]);
	double ty = 2 * (q.z * v[0] - q.x * v[2]);
	double tz = 2 * (q.x * v[1] - q.y * v[0]);
	out[0] = v[0] + q.w * tx + (q.y * tz - q.z * ty);
	out[1] = v[1] + q.w * ty + (q.z * tx - q.x * tz);
	out[2] = v[2] + q.w * tz + (q.x * ty - q.y * tx);
}

// ---- shared memory ----
static void OpenShm()
{
	int fd = shm_open(FBTCAL_SHM_NAME, O_RDWR | O_CREAT, 0600);
	if (fd < 0) { Log("shm_open failed"); return; }
	struct stat st{};
	fstat(fd, &st);
	bool fresh = st.st_size < (off_t)sizeof(FbtcalShared);
	if (fresh && ftruncate(fd, sizeof(FbtcalShared)) != 0) { close(fd); Log("ftruncate failed"); return; }
	void *p = mmap(nullptr, sizeof(FbtcalShared), PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
	close(fd);
	if (p == MAP_FAILED) { Log("mmap failed"); return; }
	g_shm = (FbtcalShared *)p;
	if (g_shm->magic != FBTCAL_MAGIC) {
		memset(g_shm, 0, sizeof(FbtcalShared));
		g_shm->magic = FBTCAL_MAGIC;
	}
	Log("shared memory ready (%zu bytes)", sizeof(FbtcalShared));
}

// ---- per-device state (only touched from the pose-update thread(s)) ----
struct DevState {
	bool serialKnown = false;
	char serial[64] = {};
};
static DevState g_dev[FBTCAL_MAX_DEVICES];
static FbtcalSlot g_slots[FBTCAL_MAX_SLOTS];
static int g_slotOf[FBTCAL_MAX_DEVICES];
static uint32_t g_cachedGen = 0xffffffffu;
static std::mutex g_mu;  // pose updates arrive from several driver threads

static void RefreshSlots()
{
	auto *gen = (std::atomic<uint32_t> *)&g_shm->appGen;
	uint32_t g1 = gen->load(std::memory_order_acquire);
	if (g1 == g_cachedGen || (g1 & 1)) return;
	FbtcalSlot copy[FBTCAL_MAX_SLOTS];
	memcpy(copy, g_shm->slots, sizeof copy);
	std::atomic_thread_fence(std::memory_order_acquire);
	if (gen->load(std::memory_order_relaxed) != g1) return;  // torn, retry next pose
	memcpy(g_slots, copy, sizeof copy);
	g_cachedGen = g1;
	for (int i = 0; i < FBTCAL_MAX_DEVICES; ++i) g_slotOf[i] = -2;  // -2 = recompute
}

static int SlotFor(uint32_t idx)
{
	if (g_slotOf[idx] != -2) return g_slotOf[idx];
	DevState &d = g_dev[idx];
	if (!d.serialKnown) {
		auto container = VRProperties()->TrackedDeviceToPropertyContainer(idx);
		ETrackedPropertyError err;
		VRProperties()->GetStringProperty(container, Prop_SerialNumber_String, d.serial, sizeof d.serial, &err);
		if (err != TrackedProp_Success) return -1;  // try again on the next pose
		d.serialKnown = true;
	}
	g_slotOf[idx] = -1;
	for (int s = 0; s < FBTCAL_MAX_SLOTS; ++s)
		if (g_slots[s].serial[0] && strncmp(g_slots[s].serial, d.serial, sizeof d.serial) == 0)
			g_slotOf[idx] = s;
	return g_slotOf[idx];
}

static void PublishRaw(uint32_t idx, const DriverPose_t &p)
{
	const HmdQuaternion_t &W = p.qWorldFromDriverRotation, &P = p.qRotation, &H = p.qDriverFromHeadRotation;
	double tmp[3], world[3];
	QRot(P, p.vecDriverFromHeadTranslation, tmp);
	for (int i = 0; i < 3; ++i) tmp[i] += p.vecPosition[i];
	QRot(W, tmp, world);
	for (int i = 0; i < 3; ++i) world[i] += p.vecWorldFromDriverTranslation[i];
	HmdQuaternion_t r = QMul(QMul(W, P), H);

	FbtcalRaw &raw = g_shm->raw[idx];
	auto *seq = (std::atomic<uint32_t> *)&raw.seq;
	uint32_t s = seq->load(std::memory_order_relaxed);
	seq->store(s + 1, std::memory_order_relaxed);
	std::atomic_thread_fence(std::memory_order_release);
	raw.valid = p.poseIsValid && p.deviceIsConnected;
	raw.timeNs = NowNs();
	memcpy(raw.pos, world, sizeof world);
	raw.rot[0] = r.w; raw.rot[1] = r.x; raw.rot[2] = r.y; raw.rot[3] = r.z;
	seq->store(s + 2, std::memory_order_release);
}

static void HandlePose(uint32_t idx, DriverPose_t &p)
{
	if (!g_shm || idx >= FBTCAL_MAX_DEVICES) return;
	PublishRaw(idx, p);
	FbtcalSlot slot;
	{
		std::lock_guard<std::mutex> lock(g_mu);
		RefreshSlots();
		int s = SlotFor(idx);
		if (s < 0) return;
		slot = g_slots[s];
	}

	bool appAlive = NowNs() - g_shm->appHeartbeatNs < 1000000000ull;
	if (slot.mode == FBTCAL_OVERRIDE && appAlive) {
		p.qWorldFromDriverRotation = {1, 0, 0, 0};
		memset(p.vecWorldFromDriverTranslation, 0, sizeof p.vecWorldFromDriverTranslation);
		p.qDriverFromHeadRotation = {1, 0, 0, 0};
		memset(p.vecDriverFromHeadTranslation, 0, sizeof p.vecDriverFromHeadTranslation);
		memcpy(p.vecPosition, slot.ovPos, sizeof p.vecPosition);
		p.qRotation = {slot.ovRot[0], slot.ovRot[1], slot.ovRot[2], slot.ovRot[3]};
		memset(p.vecVelocity, 0, sizeof p.vecVelocity);
		memset(p.vecAcceleration, 0, sizeof p.vecAcceleration);
		memset(p.vecAngularVelocity, 0, sizeof p.vecAngularVelocity);
		memset(p.vecAngularAcceleration, 0, sizeof p.vecAngularAcceleration);
		p.poseTimeOffset = 0;
		p.poseIsValid = true;
		p.result = TrackingResult_Running_OK;
	} else if (slot.mode == FBTCAL_OFFSET || slot.mode == FBTCAL_OVERRIDE) {
		// Fold the offset into driver-from-head so SteamVR's own prediction stays correct.
		HmdQuaternion_t off = {slot.offRot[0], slot.offRot[1], slot.offRot[2], slot.offRot[3]};
		double t[3];
		QRot(p.qDriverFromHeadRotation, slot.offPos, t);
		for (int i = 0; i < 3; ++i) p.vecDriverFromHeadTranslation[i] += t[i];
		p.qDriverFromHeadRotation = QMul(p.qDriverFromHeadRotation, off);
	}
}

// ---- vtable hooks ----
typedef void (*PoseUpdatedFn)(IVRServerDriverHost *, uint32_t, const DriverPose_t &, uint32_t);
typedef void *(*GetGenericInterfaceFn)(IVRDriverContext *, const char *, EVRInitError *);

static PoseUpdatedFn g_origPose = nullptr;
static void **g_poseSlot = nullptr;
static GetGenericInterfaceFn g_origGGI = nullptr;
static void **g_ggiSlot = nullptr;

static bool PatchSlot(void **slot, void *fn)
{
	long page = sysconf(_SC_PAGESIZE);
	void *start = (void *)((uintptr_t)slot & ~(uintptr_t)(page - 1));
	if (mprotect(start, page * 2, PROT_READ | PROT_WRITE | PROT_EXEC) != 0) return false;
	*slot = fn;
	mprotect(start, page * 2, PROT_READ | PROT_EXEC);
	return true;
}

static void DetourPose(IVRServerDriverHost *self, uint32_t idx, const DriverPose_t &pose, uint32_t size)
{
	DriverPose_t p = pose;
	HandlePose(idx, p);
	g_origPose(self, idx, p, size);
}

static void HookHost(void *host)
{
	if (g_poseSlot || !host) return;
	void **vtable = *(void ***)host;
	g_poseSlot = &vtable[1];  // TrackedDevicePoseUpdated
	g_origPose = (PoseUpdatedFn)*g_poseSlot;
	if (PatchSlot(g_poseSlot, (void *)&DetourPose)) Log("pose hook installed");
	else { Log("pose hook FAILED"); g_poseSlot = nullptr; }
}

static void *DetourGGI(IVRDriverContext *self, const char *ver, EVRInitError *err)
{
	void *iface = g_origGGI(self, ver, err);
	if (iface && strcmp(ver, IVRServerDriverHost_Version) == 0) HookHost(iface);
	return iface;
}

// ---- provider ----
class Provider : public IServerTrackedDeviceProvider {
public:
	EVRInitError Init(IVRDriverContext *ctx) override
	{
		VR_INIT_SERVER_DRIVER_CONTEXT(ctx);
		for (int i = 0; i < FBTCAL_MAX_DEVICES; ++i) g_slotOf[i] = -2;
		OpenShm();
		void **vtable = *(void ***)ctx;
		g_ggiSlot = &vtable[0];
		g_origGGI = (GetGenericInterfaceFn)*g_ggiSlot;
		PatchSlot(g_ggiSlot, (void *)&DetourGGI);
		HookHost(VRServerDriverHost());
		return VRInitError_None;
	}
	void Cleanup() override
	{
		if (g_poseSlot) PatchSlot(g_poseSlot, (void *)g_origPose);
		if (g_ggiSlot) PatchSlot(g_ggiSlot, (void *)g_origGGI);
		g_poseSlot = g_ggiSlot = nullptr;
		VR_CLEANUP_SERVER_DRIVER_CONTEXT();
	}
	const char *const *GetInterfaceVersions() override { return k_InterfaceVersions; }
	void RunFrame() override
	{
		if (g_shm) g_shm->driverHeartbeatNs = NowNs();
	}
	bool ShouldBlockStandbyMode() override { return false; }
	void EnterStandby() override {}
	void LeaveStandby() override {}
};

static Provider g_provider;

extern "C" __attribute__((visibility("default"))) void *HmdDriverFactory(const char *name, int *ret)
{
	if (strcmp(name, IServerTrackedDeviceProvider_Version) == 0) return &g_provider;
	if (ret) *ret = VRInitError_Init_InterfaceNotFound;
	return nullptr;
}
